source='''def transform(grid):
    """Move each nonzero color object upward until its top is at row 1."""
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    coords = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                coords.setdefault(color, []).append((r, c))
    for color, cells in coords.items():
        dr = 1 - min(r for r, _ in cells)
        for r, c in cells:
            nr = r + dr
            if 0 <= nr < h:
                out[nr][c] = color
    return out
